// Memory-Mapped File I/O (Disk interaction via Virtual Memory)
// Uses OS Paging/Demand Paging (Disk <-> RAM)

#define SIZE (1024 * 1024) 

int fd = open("data.dat", O_RDWR);

// Map disk file directly into the process address space
void* addr = mmap(
    NULL, SIZE, 
    PROT_READ | PROT_WRITE, 
    MAP_SHARED, fd, 0
);

// Accessing addr[i] triggers a Page Fault if data not in RAM
((char*)addr)[0] = 'A'; 

// Forces dirty pages back to disk
msync(addr, SIZE, MS_SYNC);

munmap(addr, SIZE);
close(fd);

// Note: Requires sys/mman.h, fcntl.h, unistd.h
